import Foundation
import XCTest
import KwipMLCore
@testable import KwipMLApp

/// Genuine CPU factory metadata, with bounded synthetic checkpoint bytes and re-pinned metrics.
/// This is a parent JSON boundary fixture, not evidence of native UI or pickle execution.
final class LossWorkflowLifecycleParentTests:XCTestCase {
    private func fixture(_ id:String)throws->[String:Data] {
        let all=try JSONDecoder().decode([String:JSONValue].self,from:Data(Self.fixtures.utf8))
        guard case .object(let item)=all[id],case .object(var manifest)=item["manifest"],case .object(var checkpoint)=manifest["checkpoint"],let metrics=item["metrics"] else {throw WorkflowPhaseError("Fixture missing")}
        let bytes=Data("independent bounded checkpoint fixture".utf8),rows=try JSONEncoder().encode(metrics)
        checkpoint["bytes"] = .integer(Int64(bytes.count));checkpoint["sha256"] = .string(WorkflowArchiveCodec.hash(bytes));checkpoint["metricsSHA256"] = .string(WorkflowArchiveCodec.hash(rows));checkpoint["completedEpoch"] = 2
        manifest["checkpoint"] = .object(checkpoint)
        return ["manifest.json":try JSONEncoder().encode(manifest),"metrics.json":rows,"checkpoint.pt":bytes]
    }
    private func mutate(_ contents:[String:Data],file:String,_ change:(inout JSONValue)->Void)throws->[String:Data] {
        var result=contents,value=try JSONDecoder().decode(JSONValue.self,from:contents[file]!);change(&value);result[file]=try JSONEncoder().encode(value)
        if file == "metrics.json" {var manifest=try JSONDecoder().decode([String:JSONValue].self,from:result["manifest.json"]!);if case .object(var checkpoint)=manifest["checkpoint"] {checkpoint["metricsSHA256"] = .string(WorkflowArchiveCodec.hash(result[file]!));manifest["checkpoint"] = .object(checkpoint)};result["manifest.json"]=try JSONEncoder().encode(manifest)}
        return result
    }
    func testAllEightPinnedObjectiveParentsAllowOnlyActualAvailableAccuracy()throws {
        for id in LossConfiguration.componentIDs {
            let record=try WorkflowLifecycleParentRecord.decode(fixture(id))
            XCTAssertTrue(record.evidence.hasObjective);XCTAssertEqual(record.metrics.count,2)
            if !["loss_cross_entropy","loss_nll"].contains(id) {XCTAssertTrue(record.metrics.allSatisfy {$0.accuracy == nil})}
        }
    }
    func testRehashedFakeAccuracyAndChangedObjectiveIdentityRefuse()throws {
        for id in LossConfiguration.componentIDs {
            let original=try fixture(id)
            if !["loss_cross_entropy","loss_nll"].contains(id) {
                let fake=try mutate(original,file:"metrics.json") {value in if case .array(var rows)=value,case .object(var row)=rows[0] {row["accuracy"] = .number(0.5);rows[0] = .object(row);value = .array(rows)}}
                XCTAssertThrowsError(try WorkflowLifecycleParentRecord.decode(fake))
            }
            let bad=try mutate(original,file:"manifest.json") {value in if case .object(var m)=value,case .object(var settings)=m["settings"] {settings["objectiveScalarization"] = .string("foreign");m["settings"] = .object(settings);value = .object(m)}}
            XCTAssertThrowsError(try WorkflowLifecycleParentRecord.decode(bad))
            let wrong=try mutate(original,file:"metrics.json") {value in if case .array(var rows)=value,case .object(var row)=rows[0],case .object(var objective)=row["objective"] {objective["componentID"] = .string("loss_foreign");row["objective"] = .object(objective);rows[0] = .object(row);value = .array(rows)}}
            XCTAssertThrowsError(try WorkflowLifecycleParentRecord.decode(wrong))
        }
    }
